/* temporary dealer.c stub */
void dealer_menu() {
    printf("Dealer panel coming soon (Team 3).\n");
}

void list_dealers() {
    int i;
    print_subtitle("All Dealers");
    print_table_dealer_header();
    for (i = 0; i < dealer_total; i++) {
        print_table_dealer_row(dealer_id[i], dealer_name[i]);
    }
    printf("+------+----------------------+\n");
}

void list_products() {
    int i;
    print_subtitle("All Products");
    print_table_product_header();
    for (i = 0; i < product_total; i++) {
        print_table_product_row(product_id[i], product_name[i], company_stock[i]);
    }
    print_table_footer();
}

void company_menu() {
    int choice;
    print_subtitle("Company Login");
    if (!verify_password()) return;
    print_success("Login successful.");

    do {
        print_menu_header("COMPANY PANEL");
        print_menu_item(1, "View All Dealers");
        print_menu_item(2, "View All Products");
        print_menu_item(3, "View Company Stock");
        print_menu_item(0, "Back to Main Menu");
        printf("\nEnter your choice: ");
        scanf("%d", &choice);

        if (choice == 1) list_dealers();
        else if (choice == 2) list_products();
        else if (choice == 3) show_company_stock();
        else if (choice != 0) print_error("Invalid choice.");
    } while (choice != 0);
}

int main() {
    int choice;
    init_data();

    do {
        print_menu_header("DISTRIBUTION MANAGEMENT SYSTEM");
        print_menu_item(1, "Company Login");
        print_menu_item(2, "Dealer Login");
        print_menu_item(3, "Retailer Login");
        print_menu_item(0, "Exit");
        printf("\nEnter your choice: ");
        scanf("%d", &choice);

        if (choice == 1) company_menu();
        else if (choice == 2) dealer_menu();
        else if (choice == 3) retailer_menu();
        else if (choice != 0) print_error("Invalid choice.");
    } while (choice != 0);

    printf("\nThank you for using DMS. Goodbye!\n\n");
    return 0;
}
